-- Aprenda se Divertindo · 123 · Constitucional, Administrativo, Raciocínio Lógico, Informática e Português · 100 questões
-- Rode depois do 122-materias-gerais.sql. Cole tudo no SQL Editor e clique em Run. Rodar de novo apenas atualiza.
-- Números 11347 a 11446: 20 de cada matéria, com 4 de cada nível (0 a 4) por matéria.

insert into public.questoes (id, materia, nivel, enunciado, opcoes, explicacao)
select id, materia, nivel, enunciado, opcoes, explicacao
from jsonb_to_recordset($q$[{"id": 11347, "materia": "const", "nivel": 0, "enunciado": "Um dos objetivos fundamentais da República, pelo art. 3º da Constituição, é:", "opcoes": ["Construir uma sociedade livre, justa e solidária", "Manter as desigualdades regionais e sociais do país", "Concentrar a renda nas capitais", "Proibir a imigração"], "explicacao": "Também erradicar a pobreza e promover o bem de todos."}, {"id": 11348, "materia": "const", "nivel": 0, "enunciado": "Nas relações internacionais, o Brasil segue, entre outros, o princípio do:", "opcoes": ["Repúdio ao terrorismo e ao racismo", "Apoio às guerras de conquista", "Fim de todas as relações", "Isolamento econômico"], "explicacao": "Art. 4º, VIII, da Constituição."}, {"id": 11349, "materia": "const", "nivel": 0, "enunciado": "Pela Constituição, a saúde é direito:", "opcoes": ["De todos e dever do Estado", "Só de quem tem plano", "Só de servidores públicos", "Só de trabalhadores formais"], "explicacao": "Art. 196 da Constituição."}, {"id": 11350, "materia": "const", "nivel": 0, "enunciado": "Pela Constituição, ninguém será submetido a tortura nem a tratamento:", "opcoes": ["Desumano ou degradante", "Médico gratuito", "Igualitário", "Educacional"], "explicacao": "Art. 5º, III."}, {"id": 11351, "materia": "const", "nivel": 1, "enunciado": "Para fazer uma reunião pacífica, sem armas, numa praça, os organizadores precisam:", "opcoes": ["Avisar antes a autoridade, sem pedir autorização", "Pedir autorização ao juiz da comarca", "Pagar uma taxa à prefeitura e esperar a licença de 30 dias", "Ter licença da polícia militar"], "explicacao": "Art. 5º, XVI, da Constituição."}, {"id": 11352, "materia": "const", "nivel": 1, "enunciado": "Pela Constituição, a lei não prejudicará o direito adquirido, o ato jurídico perfeito e a:", "opcoes": ["Coisa julgada", "Medida provisória", "Lei futura", "Vontade do governo"], "explicacao": "Art. 5º, XXXVI."}, {"id": 11353, "materia": "const", "nivel": 1, "enunciado": "Pela Constituição, a pena será cumprida em estabelecimentos distintos, conforme a natureza do delito, a idade e o:", "opcoes": ["Sexo do apenado", "Salário do apenado", "Bairro do apenado", "Time do apenado"], "explicacao": "Art. 5º, XLVIII, da Constituição."}, {"id": 11354, "materia": "const", "nivel": 1, "enunciado": "Pela Constituição, entre as garantias do Tribunal do Júri está o:", "opcoes": ["Sigilo das votações", "Voto aberto dos jurados", "Julgamento pelo juiz sozinho", "Júri formado por policiais"], "explicacao": "Art. 5º, XXXVIII, \"b\"."}, {"id": 11355, "materia": "const", "nivel": 2, "enunciado": "O Distrito Federal acumula as competências legislativas reservadas aos:", "opcoes": ["Estados e municípios", "Países estrangeiros", "Territórios federais apenas", "Tribunais superiores"], "explicacao": "Art. 32, § 1º, da Constituição."}, {"id": 11356, "materia": "const", "nivel": 2, "enunciado": "Os municípios se regem por:", "opcoes": ["Lei orgânica", "Constituição municipal", "Decreto federal", "Regimento estadual"], "explicacao": "Art. 29 da Constituição."}, {"id": 11357, "materia": "const", "nivel": 2, "enunciado": "A pequena propriedade rural trabalhada pela família não pode ser penhorada para pagar dívidas:", "opcoes": ["Da sua atividade produtiva", "De qualquer natureza, sem exceção", "De impostos federais apenas", "De pensão alimentícia apenas"], "explicacao": "Art. 5º, XXVI, da Constituição."}, {"id": 11358, "materia": "const", "nivel": 2, "enunciado": "O Brasil pode extraditar um estrangeiro acusado de crime político ou de opinião?", "opcoes": ["Não", "Sim, sempre", "Sim, se houver tratado", "Sim, se o STF quiser"], "explicacao": "Art. 5º, LII, da Constituição."}, {"id": 11359, "materia": "const", "nivel": 3, "enunciado": "Para ser ministro do STF, a pessoa deve ter:", "opcoes": ["Mais de 35 e menos de 70 anos", "Mais de 30 e menos de 65 anos", "Mais de 40 anos, sem limite", "Mais de 21 e menos de 75 anos"], "explicacao": "Art. 101 da Constituição, com a redação da EC 122/2022."}, {"id": 11360, "materia": "const", "nivel": 3, "enunciado": "O Presidente da República pode ser reeleito para:", "opcoes": ["Um único período seguinte", "Quantos mandatos quiser", "Dois períodos seguidos", "Nenhum novo mandato"], "explicacao": "Art. 14, § 5º, da Constituição."}, {"id": 11361, "materia": "const", "nivel": 3, "enunciado": "Deputados e senadores são invioláveis, civil e penalmente, por suas:", "opcoes": ["Opiniões, palavras e votos", "Dívidas particulares", "Infrações de trânsito", "Atividades empresariais"], "explicacao": "Art. 53 da Constituição."}, {"id": 11362, "materia": "const", "nivel": 3, "enunciado": "Nos crimes comuns, o Presidente da República fica suspenso das funções depois que:", "opcoes": ["O STF recebe a denúncia ou a queixa", "A polícia abre um inquérito", "Um jornal de grande circulação publica a acusação", "Um deputado faz um discurso"], "explicacao": "Art. 86, § 1º, I, da Constituição, após autorização de 2/3 da Câmara."}, {"id": 11363, "materia": "const", "nivel": 4, "enunciado": "Recebida pelo STF denúncia contra senador por crime cometido após a diplomação, o Senado pode:", "opcoes": ["Sustar o andamento da ação, pela maioria de seus membros", "Julgar o senador no lugar do STF", "Arquivar a denúncia definitivamente, sem nenhuma votação em plenário", "Decretar a prisão preventiva do senador"], "explicacao": "Art. 53, § 3º, da Constituição."}, {"id": 11364, "materia": "const", "nivel": 4, "enunciado": "A arguição de descumprimento de preceito fundamental (ADPF) é julgada pelo:", "opcoes": ["STF", "STJ", "Senado", "Tribunal de Justiça"], "explicacao": "Art. 102, § 1º, da Constituição."}, {"id": 11365, "materia": "const", "nivel": 4, "enunciado": "O Conselho Nacional do Ministério Público (CNMP) é presidido pelo:", "opcoes": ["Procurador-Geral da República", "Presidente do STF", "Ministro da Justiça", "Presidente da Câmara"], "explicacao": "Art. 130-A, I, da Constituição."}, {"id": 11366, "materia": "const", "nivel": 4, "enunciado": "Qual destes NÃO pode propor ação direta de inconstitucionalidade no STF?", "opcoes": ["Prefeito", "Governador de estado", "Presidente da República", "Conselho Federal da OAB"], "explicacao": "Art. 103 da Constituição."}, {"id": 11367, "materia": "adm", "nivel": 0, "enunciado": "Uma construtora que faz uma estrada para o governo é contratada por meio de:", "opcoes": ["Contrato administrativo", "Acordo verbal", "Herança", "Doação"], "explicacao": "A Administração formaliza a contratação em contrato, em regra após licitação."}, {"id": 11368, "materia": "adm", "nivel": 0, "enunciado": "O setor onde o servidor trabalha, como uma secretaria ou um departamento, é chamado de:", "opcoes": ["Órgão público", "Empresa privada", "Sindicato", "Cartório particular"], "explicacao": "Órgão é uma unidade de atuação, sem personalidade jurídica."}, {"id": 11369, "materia": "adm", "nivel": 0, "enunciado": "Um servidor que falta muito ao trabalho sem justificativa pode responder a:", "opcoes": ["Processo administrativo disciplinar", "Processo eleitoral do sindicato da categoria", "Inventário", "Usucapião"], "explicacao": "Para apurar infrações dos servidores."}, {"id": 11370, "materia": "adm", "nivel": 0, "enunciado": "A Secretaria de Educação do estado faz parte da Administração:", "opcoes": ["Direta", "Indireta", "Privada", "Internacional"], "explicacao": "Secretarias são órgãos da Administração direta."}, {"id": 11371, "materia": "adm", "nivel": 1, "enunciado": "Empresa pública e sociedade de economia mista fazem parte da Administração:", "opcoes": ["Indireta", "Direta", "Privada", "Concentrada"], "explicacao": "São as chamadas estatais."}, {"id": 11372, "materia": "adm", "nivel": 1, "enunciado": "Um órgão público, como um ministério, tem personalidade jurídica própria?", "opcoes": ["Não", "Sim, sempre", "Só se for federal", "Só se tiver orçamento próprio"], "explicacao": "Órgãos integram a pessoa jurídica a que pertencem."}, {"id": 11373, "materia": "adm", "nivel": 1, "enunciado": "Ao multar um motorista que estacionou em local proibido, a Administração exerce o poder:", "opcoes": ["De polícia", "Disciplinar", "Hierárquico", "Regulamentar"], "explicacao": "O poder de polícia limita a liberdade individual em favor do interesse público."}, {"id": 11374, "materia": "adm", "nivel": 1, "enunciado": "Uma fundação pública faz parte da Administração:", "opcoes": ["Indireta", "Direta", "Privada", "Concentrada"], "explicacao": "Assim como autarquias e estatais."}, {"id": 11375, "materia": "adm", "nivel": 2, "enunciado": "A presunção de legitimidade dos atos administrativos admite prova em contrário?", "opcoes": ["Sim, é uma presunção relativa", "Não, é absoluta", "Só se o Presidente da República autorizar", "Só para atos federais"], "explicacao": "Cabe ao interessado provar a ilegalidade."}, {"id": 11376, "materia": "adm", "nivel": 2, "enunciado": "Se um servidor causa dano a alguém agindo com dolo ou culpa, o Estado indeniza e depois pode cobrar do servidor por meio de:", "opcoes": ["Ação regressiva", "Habeas corpus", "Mandado de injunção", "Ação popular"], "explicacao": "Art. 37, § 6º, da Constituição."}, {"id": 11377, "materia": "adm", "nivel": 2, "enunciado": "Por ser bem público, um terreno do estado não pode ser adquirido por:", "opcoes": ["Usucapião", "Desapropriação", "Doação legal", "Permuta legal"], "explicacao": "Art. 183, § 3º, e art. 191 da Constituição."}, {"id": 11378, "materia": "adm", "nivel": 2, "enunciado": "Pela Lei 14.133/2021, a modalidade de licitação usada para vender bens móveis que não servem mais é o:", "opcoes": ["Leilão", "Pregão", "Concurso", "Diálogo competitivo"], "explicacao": "Art. 6º, XL, e art. 28 da Lei 14.133/2021."}, {"id": 11379, "materia": "adm", "nivel": 3, "enunciado": "Um ato administrativo perde a validade porque surgiu nova lei incompatível com ele. Essa extinção chama-se:", "opcoes": ["Caducidade", "Cassação", "Revogação", "Convalidação"], "explicacao": "A caducidade decorre de norma superveniente."}, {"id": 11380, "materia": "adm", "nivel": 3, "enunciado": "A concessão de serviço público é feita, mediante licitação, a:", "opcoes": ["Pessoa jurídica ou consórcio de empresas", "Qualquer pessoa física, sem prazo determinado no contrato", "Servidor público do órgão", "Órgão da própria Administração"], "explicacao": "Art. 2º, II, da Lei 8.987/1995."}, {"id": 11381, "materia": "adm", "nivel": 3, "enunciado": "Pela Constituição, o servidor estável pode perder o cargo para reduzir despesas com pessoal acima do limite legal?", "opcoes": ["Sim, observados os requisitos do art. 169", "Não, em nenhuma hipótese", "Sim, por simples decisão do chefe imediato do setor", "Só se ele aceitar"], "explicacao": "Art. 169, § 4º, da Constituição."}, {"id": 11382, "materia": "adm", "nivel": 3, "enunciado": "Na Lei 14.133/2021, o critério técnica e preço é indicado, por exemplo, para:", "opcoes": ["Serviços de natureza predominantemente intelectual", "Compra de material de limpeza comum para o escritório", "Venda de bens inservíveis", "Compra de combustível"], "explicacao": "Art. 36 da Lei 14.133/2021."}, {"id": 11383, "materia": "adm", "nivel": 4, "enunciado": "O servidor estável demitido, cuja demissão é anulada por sentença judicial, volta ao cargo por:", "opcoes": ["Reintegração", "Readaptação", "Recondução", "Reversão"], "explicacao": "Art. 41, § 2º, da Constituição."}, {"id": 11384, "materia": "adm", "nivel": 4, "enunciado": "Pela Lei de Acesso à Informação, ao pedir uma informação pública, o cidadão:", "opcoes": ["Não precisa explicar o motivo do pedido", "Precisa justificar o interesse por escrito", "Precisa pagar uma taxa fixa", "Precisa ter advogado"], "explicacao": "Art. 10, § 3º, da Lei 12.527/2011."}, {"id": 11385, "materia": "adm", "nivel": 4, "enunciado": "Pela Lei de Acesso à Informação, se o pedido de informação for negado, o cidadão pode:", "opcoes": ["Recorrer à autoridade superior em 10 dias", "Apenas desistir do pedido", "Pedir de novo só depois de 1 ano", "Reclamar só por carta ao Presidente da República"], "explicacao": "Art. 15 da Lei 12.527/2011."}, {"id": 11386, "materia": "adm", "nivel": 4, "enunciado": "O retorno à atividade do servidor aposentado por invalidez, quando cessam os motivos da aposentadoria, é a:", "opcoes": ["Reversão", "Reintegração", "Readaptação", "Recondução"], "explicacao": "Exemplo da Lei 8.112/1990 (art. 25), adotado também por estatutos estaduais."}, {"id": 11387, "materia": "rl", "nivel": 0, "enunciado": "Um curso de capacitação dura 3 semanas. Quantos dias são?", "opcoes": ["21", "18", "24", "30"], "explicacao": "3 × 7 = 21."}, {"id": 11388, "materia": "rl", "nivel": 0, "enunciado": "Um pacote tem 8 canetas. Quantas canetas há em 6 pacotes?", "opcoes": ["48", "14", "42", "56"], "explicacao": "8 × 6 = 48."}, {"id": 11389, "materia": "rl", "nivel": 0, "enunciado": "Qual número completa a sequência 5, 10, 15, __, 25?", "opcoes": ["20", "18", "22", "30"], "explicacao": "Somam-se 5 a cada termo."}, {"id": 11390, "materia": "rl", "nivel": 0, "enunciado": "Uma pizza foi cortada em 8 fatias e Ana comeu 3. Restaram:", "opcoes": ["5 fatias", "3 fatias", "4 fatias", "11 fatias"], "explicacao": "8 − 3 = 5."}, {"id": 11391, "materia": "rl", "nivel": 1, "enunciado": "Um ônibus sai às 7h50 e chega às 9h20. A viagem dura:", "opcoes": ["1h30", "1h70", "2h30", "1h10"], "explicacao": "De 7h50 a 9h20 são 90 minutos."}, {"id": 11392, "materia": "rl", "nivel": 1, "enunciado": "Duas canetas custam R$ 6. Paulo quer comprar 5. Ele vai gastar:", "opcoes": ["R$ 15", "R$ 12", "R$ 30", "R$ 10"], "explicacao": "Cada caneta custa R$ 3; 5 × 3 = 15."}, {"id": 11393, "materia": "rl", "nivel": 1, "enunciado": "Na sequência 81, 27, 9, 3, ..., o próximo número é:", "opcoes": ["1", "0", "2", "6"], "explicacao": "Divide-se por 3 a cada termo."}, {"id": 11394, "materia": "rl", "nivel": 1, "enunciado": "O triplo de 14, menos 10, é:", "opcoes": ["32", "42", "24", "38"], "explicacao": "3 × 14 = 42; 42 − 10 = 32."}, {"id": 11395, "materia": "rl", "nivel": 2, "enunciado": "Se \"todo médico é formado\", o conjunto dos médicos está:", "opcoes": ["Contido no conjunto dos formados", "Fora do conjunto dos formados", "Igual ao conjunto dos formados", "Vazio"], "explicacao": "Todo elemento de \"médicos\" pertence a \"formados\"."}, {"id": 11396, "materia": "rl", "nivel": 2, "enunciado": "Quantas diagonais tem um pentágono?", "opcoes": ["5", "10", "3", "7"], "explicacao": "n(n − 3) ÷ 2 = 5 × 2 ÷ 2 = 5."}, {"id": 11397, "materia": "rl", "nivel": 2, "enunciado": "Quanto é 15% de 300?", "opcoes": ["45", "30", "15", "60"], "explicacao": "0,15 × 300 = 45."}, {"id": 11398, "materia": "rl", "nivel": 2, "enunciado": "As notas de Lia foram 4, 6, 8 e 10. A média dela é:", "opcoes": ["7", "6", "8", "28"], "explicacao": "28 ÷ 4 = 7."}, {"id": 11399, "materia": "rl", "nivel": 3, "enunciado": "Numa caixa há 4 bombons de morango e 6 de chocolate. Pegando um sem olhar, a chance de ser de morango é:", "opcoes": ["2/5", "2/3", "1/4", "3/5"], "explicacao": "4/10 = 2/5."}, {"id": 11400, "materia": "rl", "nivel": 3, "enunciado": "A soma de dois números é 10 e a diferença entre eles é 4. O maior deles é:", "opcoes": ["7", "3", "6", "14"], "explicacao": "x + y = 10 e x − y = 4: 2x = 14, x = 7."}, {"id": 11401, "materia": "rl", "nivel": 3, "enunciado": "A proposição \"p se e somente se q\" é verdadeira quando:", "opcoes": ["p e q têm o mesmo valor lógico", "p é verdadeira e q é falsa", "p é falsa e q é verdadeira", "pelo menos uma é falsa"], "explicacao": "A bicondicional exige valores iguais."}, {"id": 11402, "materia": "rl", "nivel": 3, "enunciado": "Quantos anagramas tem a palavra OVO?", "opcoes": ["3", "6", "2", "9"], "explicacao": "3 letras com o O repetido 2 vezes: 3! ÷ 2! = 3."}, {"id": 11403, "materia": "rl", "nivel": 4, "enunciado": "Lançando dois dados comuns, a probabilidade de os dois mostrarem o mesmo número é:", "opcoes": ["1/6", "1/36", "1/12", "1/3"], "explicacao": "Há 6 casos iguais em 36: 6/36 = 1/6."}, {"id": 11404, "materia": "rl", "nivel": 4, "enunciado": "Com os algarismos 1, 2, 3 e 4, sem repetir, quantos números pares de 3 algarismos podem ser formados?", "opcoes": ["12", "24", "6", "18"], "explicacao": "Último algarismo par (2 opções) × 3 × 2 = 12."}, {"id": 11405, "materia": "rl", "nivel": 4, "enunciado": "R$ 1.000 a juros compostos de 2% ao mês, por 2 meses, resultam em:", "opcoes": ["R$ 1.040,40", "R$ 1.040,00", "R$ 1.004,00", "R$ 1.400,00"], "explicacao": "1.000 × 1,02 × 1,02 = 1.040,40."}, {"id": 11406, "materia": "rl", "nivel": 4, "enunciado": "Um conjunto tem 16 subconjuntos. Quantos elementos ele tem?", "opcoes": ["4", "8", "16", "2"], "explicacao": "2ⁿ = 16, então n = 4."}, {"id": 11407, "materia": "inf", "nivel": 0, "enunciado": "A impressora é um dispositivo de:", "opcoes": ["Saída", "Entrada", "Processamento", "Armazenamento interno"], "explicacao": "Ela coloca no papel as informações do computador."}, {"id": 11408, "materia": "inf", "nivel": 0, "enunciado": "Nos sites, o ícone de lupa geralmente serve para:", "opcoes": ["Pesquisar", "Imprimir", "Fechar a página", "Apagar dados"], "explicacao": "É o símbolo da busca."}, {"id": 11409, "materia": "inf", "nivel": 0, "enunciado": "Para mandar um e-mail, é preciso saber o:", "opcoes": ["Endereço de e-mail do destinatário", "CPF do destinatário", "Telefone fixo do destinatário", "Endereço completo da casa do destinatário"], "explicacao": "Exemplo: nome@provedor.com."}, {"id": 11410, "materia": "inf", "nivel": 0, "enunciado": "Para desligar o computador corretamente no Windows, usa-se a opção:", "opcoes": ["Desligar, no menu Iniciar", "Tirar o cabo da tomada", "Fechar o navegador", "Apertar Enter várias vezes"], "explicacao": "Assim os arquivos são salvos e o sistema fecha sem danos."}, {"id": 11411, "materia": "inf", "nivel": 1, "enunciado": "No Word em português, o atalho Ctrl + T:", "opcoes": ["Seleciona todo o texto", "Abre um novo documento", "Imprime o documento", "Fecha o programa"], "explicacao": "No Word em português, Ctrl + T seleciona tudo."}, {"id": 11412, "materia": "inf", "nivel": 1, "enunciado": "Fazer download de um arquivo significa:", "opcoes": ["Baixá-lo da internet para o aparelho", "Enviá-lo do aparelho para a internet", "Apagá-lo da lixeira", "Imprimi-lo"], "explicacao": "O contrário é upload."}, {"id": 11413, "materia": "inf", "nivel": 1, "enunciado": "Enviar uma foto do celular para um site é fazer um:", "opcoes": ["Upload", "Download", "Backup local", "Formatação"], "explicacao": "Upload é enviar; download é baixar."}, {"id": 11414, "materia": "inf", "nivel": 1, "enunciado": "Um arquivo com extensão .mp3 é, normalmente, de:", "opcoes": ["Áudio", "Planilha", "Texto", "Apresentação"], "explicacao": "MP3 é formato de música e áudio."}, {"id": 11415, "materia": "inf", "nivel": 2, "enunciado": "Compactar arquivos numa pasta .zip serve para:", "opcoes": ["Reduzir o tamanho e juntar vários arquivos", "Proteger contra todos os vírus", "Aumentar a resolução das fotos e dos vídeos guardados", "Transformar texto em planilha"], "explicacao": "Facilita o envio por e-mail."}, {"id": 11416, "materia": "inf", "nivel": 2, "enunciado": "Para capturar só um pedaço da tela no Windows 11, usa-se o atalho:", "opcoes": ["Windows + Shift + S", "Ctrl + Alt + Del", "Alt + F4", "Windows + L"], "explicacao": "Abre a Ferramenta de Captura."}, {"id": 11417, "materia": "inf", "nivel": 2, "enunciado": "No Word, o cabeçalho é:", "opcoes": ["A área no alto da página que se repete", "A primeira palavra do texto", "O título em negrito que abre o documento", "A margem esquerda da folha"], "explicacao": "Pode ter logotipo, título ou número da página."}, {"id": 11418, "materia": "inf", "nivel": 2, "enunciado": "Instalar as atualizações do sistema operacional serve, entre outras coisas, para:", "opcoes": ["Corrigir falhas de segurança", "Apagar os arquivos do usuário", "Desligar o antivírus", "Aumentar o preço do computador"], "explicacao": "As atualizações fecham brechas exploradas por invasores."}, {"id": 11419, "materia": "inf", "nivel": 3, "enunciado": "No Excel, a função =AGORA() retorna:", "opcoes": ["A data e a hora atuais", "Só o ano atual", "Só o dia da semana", "O tempo desde a abertura do arquivo"], "explicacao": "=HOJE() retorna só a data."}, {"id": 11420, "materia": "inf", "nivel": 3, "enunciado": "No Excel, o erro #NOME? geralmente indica:", "opcoes": ["Nome de função digitado errado", "Divisão por zero", "Coluna estreita demais", "Referência a célula apagada"], "explicacao": "Exemplo: =SOMMA(A1:A3)."}, {"id": 11421, "materia": "inf", "nivel": 3, "enunciado": "O programa espião que registra tudo o que a vítima digita é o:", "opcoes": ["Keylogger", "Firewall", "Antivírus", "Navegador"], "explicacao": "Usado para roubar senhas."}, {"id": 11422, "materia": "inf", "nivel": 3, "enunciado": "O ataque que derruba um site sobrecarregando-o com milhares de acessos ao mesmo tempo é o:", "opcoes": ["DDoS (negação de serviço)", "Phishing", "Backup", "Spam"], "explicacao": "Distributed Denial of Service."}, {"id": 11423, "materia": "inf", "nivel": 4, "enunciado": "No Excel, com A1 = 59, a fórmula =SE(A1>=60;\"Apto\";\"Inapto\") retorna:", "opcoes": ["Inapto", "Apto", "59", "#VALOR!"], "explicacao": "59 não é maior ou igual a 60."}, {"id": 11424, "materia": "inf", "nivel": 4, "enunciado": "No Excel, =CONT.SE(B1:B10;\"Sim\") retorna:", "opcoes": ["A quantidade de células com a palavra Sim", "A soma das células com a palavra Sim", "A posição da primeira célula com a palavra Sim", "VERDADEIRO se houver algum Sim"], "explicacao": "CONT.SE conta as células que atendem ao critério."}, {"id": 11425, "materia": "inf", "nivel": 4, "enunciado": "No Excel, =DIREITA(\"CONCURSO\";4) retorna:", "opcoes": ["URSO", "CONC", "CURSO", "4"], "explicacao": "Pega os 4 últimos caracteres."}, {"id": 11426, "materia": "inf", "nivel": 4, "enunciado": "No PROCV, colocar VERDADEIRO como último argumento faz a busca por:", "opcoes": ["Correspondência aproximada", "Correspondência exata", "Texto maiúsculo", "Últimas linhas"], "explicacao": "Com FALSO a busca é exata; com VERDADEIRO, aproximada (exige a coluna ordenada)."}, {"id": 11427, "materia": "port", "nivel": 0, "enunciado": "Complete: \"Eles ____ felizes com o resultado da prova.\"", "opcoes": ["ficaram", "ficou", "fiquei", "ficamos"], "explicacao": "Sujeito \"eles\": ficaram."}, {"id": 11428, "materia": "port", "nivel": 0, "enunciado": "O coletivo de \"músicos\" é:", "opcoes": ["orquestra", "rebanho", "enxame", "biblioteca"], "explicacao": "Também banda, conforme o caso."}, {"id": 11429, "materia": "port", "nivel": 0, "enunciado": "Um sinônimo de \"contente\" é:", "opcoes": ["feliz", "triste", "cansado", "bravo"], "explicacao": "Sinônimo tem sentido parecido."}, {"id": 11430, "materia": "port", "nivel": 0, "enunciado": "Na redação sobre animais de estimação, qual destas palavras está escrita corretamente?", "opcoes": ["cachorro", "cachoro", "caxorro", "cachorrro"], "explicacao": "Escreve-se com ch e rr."}, {"id": 11431, "materia": "port", "nivel": 1, "enunciado": "Em \"As crianças brincam no parque\", o núcleo do sujeito é:", "opcoes": ["crianças", "parque", "brincam", "as"], "explicacao": "É a palavra principal do sujeito."}, {"id": 11432, "materia": "port", "nivel": 1, "enunciado": "A palavra \"guarda-chuva\" é formada por:", "opcoes": ["Composição", "Derivação prefixal", "Derivação sufixal", "Abreviação"], "explicacao": "Junta duas palavras: guarda + chuva."}, {"id": 11433, "materia": "port", "nivel": 1, "enunciado": "O plural de \"mês\" é:", "opcoes": ["meses", "mêses", "mês", "mezes"], "explicacao": "Mês, meses (sem acento no plural)."}, {"id": 11434, "materia": "port", "nivel": 1, "enunciado": "A frase \"Que dia lindo!\" é:", "opcoes": ["Exclamativa", "Interrogativa", "Imperativa", "Declarativa negativa"], "explicacao": "Expressa emoção e termina com exclamação."}, {"id": 11435, "materia": "port", "nivel": 2, "enunciado": "Pelo Novo Acordo Ortográfico, a forma correta é:", "opcoes": ["ideia", "idéia", "idêia", "ideía"], "explicacao": "Os ditongos abertos ei e oi das paroxítonas perderam o acento."}, {"id": 11436, "materia": "port", "nivel": 2, "enunciado": "Pelo Novo Acordo Ortográfico, qual destas formas de escola de direção está correta?", "opcoes": ["autoescola", "auto-escola", "auto escola", "autoêscola"], "explicacao": "Prefixo terminado em vogal + palavra iniciada por vogal diferente: junta sem hífen."}, {"id": 11437, "materia": "port", "nivel": 2, "enunciado": "Complete: \"Saímos ___ pressas para não perder o ônibus.\"", "opcoes": ["às", "as", "ás", "hás"], "explicacao": "Locução adverbial feminina: às pressas."}, {"id": 11438, "materia": "port", "nivel": 2, "enunciado": "Complete: \"Ele se sentiu ____ depois do almoço.\"", "opcoes": ["mal", "mau", "maus", "maul"], "explicacao": "\"Mal\" é advérbio (oposto de bem)."}, {"id": 11439, "materia": "port", "nivel": 3, "enunciado": "Complete: \"É ____ paciência para estudar.\"", "opcoes": ["necessário", "necessária", "necessárias", "necessários"], "explicacao": "Sem artigo antes do substantivo, a expressão fica invariável. Com artigo: \"é necessária a paciência\"."}, {"id": 11440, "materia": "port", "nivel": 3, "enunciado": "Assinale a frase em que o verbo \"haver\" está correto:", "opcoes": ["Deve haver soluções para o caso.", "Devem haver soluções para o caso.", "Houveram soluções para o caso.", "Haviam soluções para o caso."], "explicacao": "\"Haver\" no sentido de existir é impessoal, e o auxiliar também fica no singular."}, {"id": 11441, "materia": "port", "nivel": 3, "enunciado": "Na norma-padrão, complete: \"Obedeça ___ sinalização.\"", "opcoes": ["à", "a", "há", "as"], "explicacao": "Obedecer a + a sinalização = à."}, {"id": 11442, "materia": "port", "nivel": 3, "enunciado": "Em \"Os alunos que estudaram passaram\", sem vírgulas, entende-se que:", "opcoes": ["Só os que estudaram passaram", "Todos os alunos passaram", "Nenhum aluno estudou", "Todos estudaram, mas ninguém passou"], "explicacao": "A oração adjetiva restritiva limita o sentido."}, {"id": 11443, "materia": "port", "nivel": 4, "enunciado": "Em \"Ana e Bia chegaram; esta trouxe o bolo\", o pronome \"esta\" refere-se a:", "opcoes": ["Bia", "Ana", "Às duas", "Ao bolo"], "explicacao": "\"Esta\" retoma o termo mais próximo."}, {"id": 11444, "materia": "port", "nivel": 4, "enunciado": "Em \"Não só estudou, mas também trabalhou\", há relação de:", "opcoes": ["Adição", "Oposição", "Conclusão", "Causa"], "explicacao": "\"Não só... mas também\" soma ideias."}, {"id": 11445, "materia": "port", "nivel": 4, "enunciado": "Em \"Espero que você passe\", o \"que\" é:", "opcoes": ["Conjunção integrante", "Pronome relativo", "Advérbio", "Preposição"], "explicacao": "Introduz oração substantiva objetiva direta."}, {"id": 11446, "materia": "port", "nivel": 4, "enunciado": "Em \"Vi o filme de que você falou\", a preposição \"de\" aparece porque:", "opcoes": ["Quem fala, fala de algo", "Quem vê, vê de algo", "O filme exige preposição", "É um erro de concordância"], "explicacao": "A regência do verbo da oração adjetiva determina a preposição antes do relativo."}]$q$::jsonb)
  as x(id integer, materia text, nivel smallint, enunciado text, opcoes jsonb, explicacao text)
on conflict (id) do update set materia = excluded.materia, nivel = excluded.nivel, enunciado = excluded.enunciado, opcoes = excluded.opcoes, explicacao = excluded.explicacao;

select setval(pg_get_serial_sequence('public.questoes', 'id'), (select max(id) from public.questoes where id < 1000000));
select materia, count(*) as questoes_novas from public.questoes where id between 11347 and 11446 group by materia order by materia;
select public.questoes_versao() as nova_versao;
